function extractHex(obj){
  const results=[];
  function walk(o){
    if(typeof o==='string'){
      const cleaned=o.replace(/[\s\r\n]/g,'');
      if(/^[0-9A-Fa-f]+$/.test(cleaned)&&cleaned.length>=16&&cleaned.length%2===0)results.push(cleaned);
    }else if(o&&typeof o==='object'){
      for(const k in o)walk(o[k]);
    }
  }
  walk(obj);
  return results;
}
