function srName(addr){return srMeta[addr]?.[0]||'未收录';}
function srDecoded(addr,raw){
  const p=srMeta[addr];if(!p)return '—';
  const [,type,scale,unit,enums,mode]=p;
  if(mode==='words')return '多寄存器字段，单字未换算';
  if(mode==='clock'){const h=raw>>8,m=raw&255;return h<24&&m<60?String(h).padStart(2,'0')+':'+String(m).padStart(2,'0'):'时间值无效';}
  if(Object.keys(enums).length)return enums[String(raw)]||'未识别';
  const signed=type==='S16'&&raw>=32768?raw-65536:raw;
  if(scale!==null){const value=signed*scale;const decimals=scale===0.1?1:scale===0.01?2:0;return value.toFixed(decimals)+(unit?(unit==='℃'?'℃':' '+unit):'');}
  if(type==='S16'&&signed!==raw)return String(signed)+(unit?(' '+unit):'');
  return unit?String(signed)+' '+unit:'—';
}
const fwDefaultColumns=['直流风扇转速','环境温度（TAO）','线圈温度传感器 (TRC)','驱动器运行频率','低压开关状态','低压压力传感器压力值','高压压力传感器压力值','吸气饱和温度','吸气压力值'];
let fwColumns=new Set(fwDefaultColumns);
function fwReset(){if(fwQuery.busy){fwQueryStatus('请先停止查询，再清空数据');return;}fwState.pending={};fwState.count=null;fwState.selected=null;fwState.types=[];fwState.times=[];fwState.samples=[];fwState.issues=[];fwRender();}
function fwHex(bytes){return bytes.map(x=>x.toString(16).padStart(2,'0').toUpperCase()).join(' ');}
function fwDate(bytes){
  if(bytes.length<6)return '';
  const [y,m,d,h,min,s]=bytes, year=2000+y;
  const t=new Date(Date.UTC(year,m-1,d,h,min,s));
  if(m<1||m>12||d<1||h>23||min>59||s>59||t.getUTCFullYear()!==year||t.getUTCMonth()!==m-1||t.getUTCDate()!==d)return '';
  const z=n=>String(n).padStart(2,'0');
  return `${year}-${z(m)}-${z(d)} ${z(h)}:${z(min)}:${z(s)}`;
}
function fwFrame(bytes,stream='import'){
  if(bytes.length<13||bytes[0]!==0x7f||bytes[1]!==0x7f)return;
  if(bytes[2]!==0x11&&bytes[2]!==0x91)return;
  const len=(bytes[7]<<8)|bytes[8], end=9+len;
  if(bytes.length!==end+4||bytes[end+2]!==0xf7||bytes[end+3]!==0xf7)return;
  const actual=bytes[end]|(bytes[end+1]<<8), expected=crc16(bytes.slice(2,end));
  if(actual!==expected){fwState.issues.push('外层 CRC 校验失败，已忽略一帧');fwState.revision++;return;}
  const cmd=bytes[2], data=bytes.slice(9,end);
  if(cmd===0x11 && data.length===8 && data[1]===3){
    if(crc16(data.slice(0,6))!==(data[6]|data[7]<<8)){fwState.issues.push('查询指令 CRC 校验失败');fwState.revision++;return;}
    if(fwState.pending[stream]){
      if(!fwState.pending[stream].ambiguous){fwState.issues.push('同一连接存在未完成的并发查询，无法安全匹配地址，请清空数据后重试');fwState.revision++;}
      fwState.pending[stream]={ambiguous:true};return;
    }
    fwState.pending[stream]={unit:data[0],address:(data[2]<<8)|data[3],count:(data[4]<<8)|data[5]};
    return;
  }
  if(cmd!==0x91||data.length<3||data[1]!==3)return;
  const p=fwState.pending[stream];
  if(!p||p.ambiguous||p.unit!==data[0])return;
  delete fwState.pending[stream];
  const payload=data.slice(3);
  if(p.address===0x1963&&p.count===1&&data[2]===2&&payload.length===2){
    srState.type=(payload[0]<<8)|payload[1];
  }else if(p.address===0x1964&&p.count===2&&data[2]===4&&payload.length===4){
    srState.count=(payload[0]<<8)|payload[1];srState.offset=(payload[2]<<8)|payload[3];
  }else if(p.address===0x1966&&p.count===120&&data[2]===240&&payload.length===240&&srState.type===0&&srState.offset!==null){
    const rows=[];
    for(let i=0;i<15;i++){
      const b=payload.slice(i*16,i*16+16);if(b.every(x=>x===0))continue;
      const u=n=>(b[n]<<8)|b[n+1];
      rows.push({time:fwDate(b.slice(0,6))||fwHex(b.slice(0,6)),channel:u(6),address:u(8),before:u(10),after:u(12),tail:u(14)});
    }
    srState.rows=rows;srState.pageOffset=srState.offset;
  }else if(p.address===0xB1BB && p.count===1 && data[2]===2 && payload.length===2){
    fwState.count=(payload[0]<<8)|payload[1];
  }else if(p.address===0xB23C && p.count===1 && data[2]===2 && payload.length===2){
    fwState.selected=(payload[0]<<8)|payload[1];
  }else if(p.address===0xB1BC && p.count===32 && data[2]===64 && payload.length===64){
    fwState.types=[];
    for(let i=0;i<32;i++)fwState.types.push((payload[i*2]<<8)|payload[i*2+1]);
  }else if(p.address===0xB1DC && p.count===96 && data[2]===192 && payload.length===192){
    fwState.times=[];
    for(let i=0;i<32;i++)fwState.times.push(fwDate(payload.slice(i*6,i*6+6))||fwHex(payload.slice(i*6,i*6+6)));
  }else if(p.count===255 && data[2]===255 && payload.length===512){
    const row={address:p.address,time:fwDate(payload.slice(0,6)),values:{}};
    for(const f of fwFields){const value=payload[f[1]]|(payload[f[1]+1]<<8);row.values[f[0]]=f[2]&&value>=32768?value-65536:value;}
    const old=fwState.samples.findIndex(x=>x.address===row.address);
    if(old>=0)fwState.samples[old]=row;else fwState.samples.push(row);
  }else if(p.address===0xB1BB||p.address===0xB1BC||p.address===0xB1DC||p.count===255){
    fwState.issues.push('未识别的录波响应：地址 '+p.address.toString(16).toUpperCase()+'，数据 '+payload.length+' 字节');
  }else{
    return;
  }
  fwState.revision++;
}
function fwProcessHex(text,stream='import'){
  const cleaned=String(text).replace(/\s/g,'');
  if(!/^(?:[0-9a-fA-F]{2})+$/.test(cleaned))return;
  const b=hexToBytes(cleaned);let i=0;
  while(i+13<=b.length){
    if(b[i]!==0x7f||b[i+1]!==0x7f){i++;continue;}
    const len=(b[i+7]<<8)|b[i+8], end=i+13+len;
    if(end>b.length){fwState.issues.push('报文不完整，无法解析');break;}
    if(b[i+11+len]!==0xf7||b[i+12+len]!==0xf7){i++;continue;}
    fwFrame(b.slice(i,end),stream);i=end;
  }
}
function fwImport(text){
  let found=false;
  const normalized=String(text).replace(/\\?\s+(?=Rev:)/g,'\n');
  for(const line of normalized.split(/\r?\n/)){
    const m=line.match(/^\s*(Send|Rev):\s*(.*)$/i);
    if(!m)continue;found=true;
    if(m[1].toLowerCase()==='rev'&&/^<empty>/i.test(m[2])){delete fwState.pending.import;fwState.issues.push('查询超时，无响应');continue;}
    fwProcessHex(m[2].trim().replace(/\\$/,''));
  }
  if(!found)fwProcessHex(String(text).trim());
  fwRender();
}
function fwObserve(data,stream,direction){
  // 自动操作由专用流程配对；只检查是否有不同的下发指令干扰。
  if(fwQuery.busy){
    if(direction==='outgoing'&&fwQuery.expectedHex){
      try{
        let hexes=[];
        if(typeof data==='string'){try{hexes=extractHex(JSON.parse(data));}catch(e){hexes=[data];}}
        else if(data instanceof ArrayBuffer)hexes=[fwHex(Array.from(new Uint8Array(data)))];
        else if(ArrayBuffer.isView(data))hexes=[fwHex(Array.from(new Uint8Array(data.buffer,data.byteOffset,data.byteLength)))];
        for(const h of hexes){const clean=String(h).replace(/\s/g,'').toUpperCase();
          if(/^7F7F11[0-9A-F]+$/.test(clean)&&clean!==fwQuery.expectedHex)fwQuery.interference=true;
        }
      }catch(e){}
    }
    return;
  }
  try{
    const revision=fwState.revision,issues=fwState.issues.length;
    if(typeof data==='string'){
      let values=[];try{values=extractHex(JSON.parse(data));}catch(e){values=[data];}
      for(const value of values)fwProcessHex(value,stream);
    }else if(data instanceof ArrayBuffer)fwProcessHex(fwHex(Array.from(new Uint8Array(data))),stream);
    else if(ArrayBuffer.isView(data))fwProcessHex(fwHex(Array.from(new Uint8Array(data.buffer,data.byteOffset,data.byteLength))),stream);
    if(revision!==fwState.revision||issues!==fwState.issues.length)fwRender();
  }catch(e){fwState.issues.push('录波监听失败：'+e.message);}
}
function fwRender(){
  srRender();
  const info=document.getElementById('fox-fw-info'),events=document.getElementById('fox-fw-events'),table=document.getElementById('fox-fw-table');
  if(!info||!events||!table)return;
  info.textContent=`事件总数 ${fwState.count===null?'未知':fwState.count}；查询索引 ${fwState.selected===null?'未知':fwState.selected}；录波 ${fwState.samples.length} 包；事件类型 ${fwState.types.length} 项；事件时间 ${fwState.times.length} 项；提示 ${fwState.issues.length} 条。`;
  const eventCount=Math.max(fwState.types.length,fwState.times.length);
  fwRenderTable(events,['返回顺序','事件类型','事件时间'],Array.from({length:eventCount},(_,i)=>[i+1,fwState.types[i]??'—',fwState.times[i]||'—']),'暂无事件类型或时间数据');
  const columns=fwFields.map(f=>f[0]).filter(name=>fwColumns.has(name));
  const rows=fwState.samples.slice().sort((a,b)=>a.address-b.address).map(r=>[r.address.toString(16).toUpperCase(),r.time||'时间无效',...columns.map(k=>r.values[k]??'—')]);
  fwRenderTable(table,['包地址','设备时间',...columns.map(x=>x+'（原始值）')],rows,'暂无录波采样数据');
  const issues=document.getElementById('fox-fw-issues');if(issues)issues.textContent=fwState.issues.length?'提示：'+fwState.issues.slice(-5).join('；'):'';
}
function fwRenderTable(container,headers,rows,empty){
  const top=container.scrollTop,left=container.scrollLeft;
  if(!rows.length){const p=document.createElement('div');p.className='fox-fw-empty';p.textContent=empty;container.replaceChildren(p);return;}
  const table=document.createElement('table');table.className='fox-fw-grid';
  const thead=document.createElement('thead'),tr=document.createElement('tr');
  for(const label of headers){const th=document.createElement('th');th.textContent=label;tr.appendChild(th);}
  thead.appendChild(tr);table.appendChild(thead);
  const tbody=document.createElement('tbody');
  for(const row of rows){const line=document.createElement('tr');for(const value of row){const cell=document.createElement('td');cell.textContent=String(value);line.appendChild(cell);}tbody.appendChild(line);}
  table.appendChild(tbody);container.replaceChildren(table);container.scrollTop=top;container.scrollLeft=left;
}
function srRender(){
  const info=document.getElementById('fox-sr-info'),table=document.getElementById('fox-sr-table');if(!info||!table)return;
  info.textContent=`记录类型 ${srState.type===null?'未知':srState.type}；记录总数 ${srState.count===null?'未知':srState.count}；当前偏移 ${srState.pageOffset===null?'未知':srState.pageOffset}；本页 ${srState.rows.length} 条。`;
  const rows=srState.rows.map((r,i)=>[srState.pageOffset===null?i+1:srState.pageOffset+i+1,r.time,r.channel,r.address,srName(r.address),r.before,r.after,srDecoded(r.address,r.before),srDecoded(r.address,r.after)]);
  fwRenderTable(table,['序号','设备时间','通道号','设置地址','参数名称','修改前原始值','修改后原始值','修改前说明','修改后说明'],rows,'暂无设置记录');
}
function srStatus(text){const e=document.getElementById('fox-sr-status');if(e)e.textContent=text;}
function srExport(){
  if(!srState.rows.length){alert('请先查询设置记录');return;}
  const rows=[['序号','设备时间','通道号','设置地址','参数名称','修改前原始值','修改后原始值','修改前说明','修改后说明'],...srState.rows.map((r,i)=>[(srState.pageOffset||0)+i+1,r.time,r.channel,r.address,srName(r.address),r.before,r.after,srDecoded(r.address,r.before),srDecoded(r.address,r.after)])];
  const filename='设置记录_偏移'+(srState.pageOffset??'未知')+'_'+new Date().toISOString().slice(0,19).replace(/[:T]/g,'-');
  loadXlsxLib(ok=>{if(ok&&window.XLSX){try{const wb=XLSX.utils.book_new(),ws=XLSX.utils.aoa_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'设置记录');XLSX.writeFile(wb,filename+'.xlsx');return;}catch(e){}}
    const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
    const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=filename+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  });
}
function fwRenderColumns(){
  const list=document.getElementById('fox-fw-column-list');if(!list)return;
  const keyword=(document.getElementById('fox-fw-column-search').value||'').trim().toLowerCase();
  list.replaceChildren();
  for(const [name] of fwFields){
    if(keyword&&!name.toLowerCase().includes(keyword))continue;
    const label=document.createElement('label');label.className='fox-fw-column-item';
    const box=document.createElement('input');box.type='checkbox';box.checked=fwColumns.has(name);
    box.onchange=()=>{if(box.checked)fwColumns.add(name);else fwColumns.delete(name);fwRender();};
    label.appendChild(box);label.appendChild(document.createTextNode(' '+name));list.appendChild(label);
  }
}
function fwExport(){
  if(!fwState.samples.length){alert('请先导入或接收录波数据');return;}
  const headers=['包地址（十六进制）','设备时间',...fwFields.map(f=>f[0]+'（原始值）')];
  const rows=[headers,...fwState.samples.slice().sort((a,b)=>a.address-b.address).map(r=>[r.address.toString(16).toUpperCase(),r.time,...fwFields.map(f=>r.values[f[0]])])];
  const filename='故障录波_'+(fwState.selected===null?'未确认事件':'事件'+fwState.selected)+'_'+new Date().toISOString().slice(0,19).replace(/[:T]/g,'-');
  loadXlsxLib(ok=>{
    if(ok&&window.XLSX){try{const wb=XLSX.utils.book_new(),ws=XLSX.utils.aoa_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'录波原始数据');XLSX.writeFile(wb,filename+'.xlsx');return;}catch(e){}}
    const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
    const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=filename+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  });
}
let fwPreviousDocument=null;
function fwShowCurve(){
  const rows=fwState.samples.map(r=>({sample:r,t:r.time?parseCsvTime(r.time):NaN})).filter(x=>Number.isFinite(x.t)).sort((a,b)=>a.t-b.t||a.sample.address-b.sample.address);
  if(rows.length<2){alert('至少需要两条带有效设备时间的录波数据才能查看曲线');return;}
  if(!fwPreviousDocument&&fileBuf.length&&!fileTimeAxis){
    fwPreviousDocument={buf:fileBuf,params:fileParams,selected:fileSelected.slice(),name:fileImportName,timeAxis:fileTimeAxis};
  }
  fileParams=fwFields.map(([name])=>{
    const temperature=name.includes('温度');
    return {name:name+(temperature?'（℃）':'（原始值）'),orig:name,scale:temperature?0.1:1,unit:temperature?'℃':'',precision:temperature?1:null};
  });
  fileBuf=rows.map((item,i)=>{
    const data={};for(const p of fileParams){const value=item.sample.values[p.orig];if(typeof value==='number'&&Number.isFinite(value))data[p.name]=p.precision===1?Number((value/10).toFixed(1)):value;}
    const previous=i?rows[i-1].sample.address:null,current=item.sample.address;
    const inRange=a=>a>=0xB23D&&a<=0xB27C;
    const gapBefore=previous!==null&&inRange(previous)&&inRange(current)&&((current-previous+64)%64)!==1;
    return {t:item.t,data,gapBefore};
  });
  const preferred='直流风扇转速（原始值）';
  fileSelected=[fileParams.some(p=>p.name===preferred)?preferred:fileParams[0].name];
  filePendingName='';fileKeyword='';fileDropIdx=-1;fileHoverIdx=-1;filePins=[];filePinSeq=0;fileTimeAxis=true;
  fileImportName=`故障录波${fwState.selected===null?'':' 事件'+fwState.selected}（温度 ℃，其他原始值，${rows.length}/${fwState.samples.length} 个有效时间）`;
  const input=document.getElementById('fox-file-input-sel');if(input)input.value='';
  const restore=document.getElementById('fox-file-restore');if(restore)restore.style.display=fwPreviousDocument?'inline-block':'none';
  renderFileChips();
  const tab=document.querySelector('.fox-view-btn[data-view="file"]');if(tab)tab.click();else drawFileCurve();
}
function fwRestoreDocument(){
  if(!fwPreviousDocument)return;
  fileBuf=fwPreviousDocument.buf;fileParams=fwPreviousDocument.params;fileSelected=fwPreviousDocument.selected;fileImportName=fwPreviousDocument.name;fileTimeAxis=fwPreviousDocument.timeAxis;
  fwPreviousDocument=null;filePendingName='';fileKeyword='';fileDropIdx=-1;fileHoverIdx=-1;filePins=[];filePinSeq=0;
  const input=document.getElementById('fox-file-input-sel');if(input)input.value='';
  const restore=document.getElementById('fox-file-restore');if(restore)restore.style.display='none';
  renderFileChips();drawFileCurve();
}

// 通过批量 Console 查询；设置事件索引使用 06，其余读取使用 03。
const fwQuery = {busy:false, stopped:false, observer:null,expectedHex:'',interference:false};
function fwFrameForRequest(func,address,value){
  const inner=func===16?[1,func,address>>8,address&255,0,1,2,value>>8,value&255]:[1,func,address>>8,address&255,value>>8,value&255];
  const c=crc16(inner);inner.push(c&255,c>>8);
  const body=[0x11,0x12,0x34,0x56,0x78,0,inner.length,...inner];
  const outer=crc16(body);
  return [0x7f,0x7f,...body,outer&255,outer>>8,0xf7,0xf7];
}
function fwReadFrame(address,count){return fwFrameForRequest(3,address,count);}
function fwQueryStatus(text){const e=document.getElementById('fox-fw-query-status');if(e)e.textContent=text;}
function fwPageControls(){
  if(location.hostname!=='linkdiag-eu.foxess.cloud'||!location.pathname.startsWith('/batch-console'))throw new Error('请在设备连接检测平台的 Console 页面使用');
  const input=document.querySelector('[aria-label="批量下发内容"],textarea[placeholder*="输入完整下发"]');
  const sn=document.querySelector('[aria-label="设备 SN 列表"],textarea[placeholder*="最多 100 个 SN"]');
  const button=Array.from(document.querySelectorAll('button')).find(e=>e.textContent.trim()==='批量下发');
  if(!input||!sn||!button)throw new Error('未找到页面的连接或下发控件，请刷新后重试');
  const devices=sn.value.trim().split(/[\s,;，；]+/).filter(Boolean);
  if(devices.length!==1)throw new Error('请只连接一台设备后再操作');
  if(button.disabled||!document.body.innerText.includes('全部已连接并监听'))throw new Error('设备尚未连接并监听');
  return {input,button,sn:devices[0]};
}
function fwSetPageInput(input,value){
  const proto=input.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;
  const setter=Object.getOwnPropertyDescriptor(proto,'value').set;
  setter.call(input,value);input.dispatchEvent(new Event('input',{bubbles:true}));
}
function fwFindResponses(){
  return Array.from(document.querySelectorAll('article,[role="article"]')).map(e=>e.innerText||e.textContent||'');
}
function fwExchange(func,address,value,maintenanceRead=false){
  return new Promise((resolve,reject)=>{
    const query=maintenanceRead?snMaintenanceReads.find(item=>item.address===address):null;
    if(maintenanceRead&&(!query||func!==3||value!==1))throw new Error('未知的维护状态查询');
    const page=maintenanceRead?snVerifiedPage():fwPageControls();
    const cmd=query?query.frame:fwFrameForRequest(func,address,value), cmdText=fwHex(cmd), initial=new Set(fwFindResponses());
    const verifyTarget=()=>{
      const current=snVerifiedPage();
      if(current.sn!==page.sn||current.input!==page.input||current.button!==page.button)throw new Error('连接目标已变化，请重新查询');
    };
    fwQuery.expectedHex=cmdText.replace(/\s/g,'');
    let done=false,sent=!maintenanceRead,timer=null,poll=null;
    const finish=(error,payload)=>{
      if(done)return;done=true;clearTimeout(timer);clearInterval(poll);
      if(fwQuery.observer)fwQuery.observer.disconnect();fwQuery.observer=null;fwQuery.expectedHex='';
      delete fwState.pending.query;
      try{if(page.input.value===cmdText)fwSetPageInput(page.input,fwQuery.previousInput);}catch(e){}
      error?reject(error):resolve(payload);
    };
    const check=()=>{
      if(fwQuery.stopped){finish(new Error('已停止查询'));return;}
      if(fwQuery.interference){finish(new Error('检测到其他下发指令，已停止查询以避免数据错配'));return;}
      if(!sent)return;
      for(const text of fwFindResponses()){
        if(initial.has(text)||!/\bRECV\b/i.test(text))continue;
        const matches=text.match(/7F\s+7F\s+91(?:\s+[0-9A-F]{2})+\s+F7\s+F7/gi)||[];
        for(const raw of matches){
          const bytes=hexToBytes(raw),n=(bytes[7]<<8)|bytes[8];
          if(bytes.length!==n+13||cmd.slice(3,7).some((byte,i)=>bytes[i+3]!==byte))continue;
          if(crc16(bytes.slice(2,-4))!==(bytes[bytes.length-4]|bytes[bytes.length-3]<<8))continue;
          const payload=bytes.slice(9,9+n);
          if(payload[0]!==1||payload[1]!==func)continue;
          if(maintenanceRead){
            if(payload[2]!==2||(payload.length!==5&&payload.length!==7))continue;
            if(payload.length===7&&crc16(payload.slice(0,5))!==(payload[5]|payload[6]<<8))continue;
            try{verifyTarget();}catch(e){finish(e);return;}
            finish(null,payload);return;
          }
          if(func===3){const expected=value===255?512:value*2;if(payload.length!==expected+3)continue;}
          else if(func===6){
            if(payload.length!==6&&payload.length!==8)continue;
            if(payload[2]!==address>>8||payload[3]!== (address&255)||payload[4]!==value>>8||payload[5]!== (value&255))continue;
            if(payload.length===8&&crc16(payload.slice(0,6))!==(payload[6]|payload[7]<<8))continue;
          }else if(func===16){
            if(payload.length!==6&&payload.length!==8)continue;
            if(payload[2]!==address>>8||payload[3]!== (address&255)||payload[4]!==0||payload[5]!==1)continue;
            if(payload.length===8&&crc16(payload.slice(0,6))!==(payload[6]|payload[7]<<8))continue;
          }else continue;
          if(func===3){fwProcessHex(cmdText,'query');fwProcessHex(raw,'query');fwRender();}
          finish(null,payload);return;
        }
      }
    };
    fwQuery.observer=new MutationObserver(check);fwQuery.observer.observe(document.body,{childList:true,subtree:true,characterData:true});
    timer=setTimeout(()=>finish(new Error('设备回包超时或未能识别回包，查询已停止')),8000);
    poll=setInterval(check,200);
    fwQuery.previousInput=page.input.value;
    try{fwSetPageInput(page.input,cmdText);}catch(e){finish(e);return;}
    setTimeout(()=>{
      if(done)return;
      if(fwQuery.stopped){finish(new Error('已停止查询'));return;}
      if(fwQuery.interference){finish(new Error('检测到其他下发指令，已停止查询以避免数据错配'));return;}
      try{
        if(maintenanceRead){
          verifyTarget();
          if(page.input.value!==cmdText)throw new Error('下发内容已变化，请重新查询');
        }
        sent=true;
        page.button.click();
      }catch(e){finish(e);}
    },100);
  });
}
function fwReadOne(address,count){return fwExchange(3,address,count);}
function fwSetIndex(index){return fwExchange(6,0xB23C,index);}
async function srQuery(){
  if(fwQuery.busy){srStatus('已有查询或写入进行中');return;}
  const input=document.getElementById('fox-sr-offset'),text=input.value;
  if(!/^\d+$/.test(text)||Number(text)>65535){srStatus('查询偏移须为 0～65535 的整数');return;}
  const offset=Number(text);srState.rows=[];srState.pageOffset=null;srState.type=null;srState.count=null;srState.offset=null;srRender();
  fwQuery.busy=true;fwQuery.stopped=false;fwQuery.interference=false;
  try{
    srStatus('正在读取记录类型…');await fwReadOne(0x1963,1);
    if(srState.type===null)throw new Error('未能确认记录类型');
    if(srState.type!==0){
      srStatus('正在切换至设置记录类型…');await fwExchange(16,0x1963,0);
      srState.type=null;await fwReadOne(0x1963,1);
      if(srState.type!==0)throw new Error('设置记录类型回读不一致');
    }
    srStatus('正在读取记录总数…');await fwReadOne(0x1964,2);
    if(srState.count===null||srState.offset===null)throw new Error('未能确认记录总数和查询偏移');
    if(!srState.count){srStatus('设备没有设置记录');return;}
    if(offset>=srState.count)throw new Error(`偏移 ${offset} 超出记录总数 ${srState.count}`);
    if(srState.offset!==offset){
      srStatus(`正在设置查询偏移 ${offset}…`);await fwExchange(16,0x1965,offset);
      srState.offset=null;await fwReadOne(0x1964,2);
      if(srState.offset!==offset)throw new Error('查询偏移回读不一致，已停止读取');
    }
    srStatus('正在读取本页设置记录…');await fwReadOne(0x1966,120);
    if(srState.pageOffset!==offset)throw new Error('未能解析设置记录响应');
    srStatus(`查询完成，获取 ${srState.rows.length} 条记录`);
  }catch(e){srStatus('查询失败：'+e.message);}
  finally{fwQuery.busy=false;srRender();}
}
async function fwRunQuery(items,label){
  if(fwQuery.busy){fwQueryStatus('已有查询进行中');return;}
  fwQuery.busy=true;fwQuery.stopped=false;fwQuery.interference=false;
  try{
    for(let i=0;i<items.length;i++){
      fwQueryStatus(`${label}：正在读取 ${i+1}/${items.length}`);
      await fwReadOne(items[i][0],items[i][1]);
    }
    fwQueryStatus(`${label}：完成 ${items.length}/${items.length}`);
  }catch(e){fwQueryStatus(`${label}：${e.message}`);}
  finally{fwQuery.busy=false;}
}
async function fwStartPackets(){
  if(fwQuery.busy){fwQueryStatus('已有查询进行中');return;}
  const eventText=document.getElementById('fox-fw-event-index').value;
  if(!/^\d+$/.test(eventText)){fwQueryStatus('请输入事件查询索引');return;}
  const event=Number(eventText);
  if(!Number.isSafeInteger(event)||event<0||event>65535){fwQueryStatus('查询索引须为 0～65535 的整数');return;}
  if(fwState.samples.length){fwQueryStatus('请先导出并清空已有录波，避免混入其他事件');return;}
  fwQuery.busy=true;fwQuery.stopped=false;fwQuery.interference=false;fwState.selected=null;
  try{
    fwQueryStatus(`正在设置事件查询索引 ${event}`);await fwSetIndex(event);
    fwQueryStatus('正在确认事件查询索引');await fwReadOne(0xB23C,1);
    if(fwState.selected!==event)throw new Error('索引回读不一致，已停止读取');
    for(let i=0;i<64;i++){
      fwQueryStatus(`查询索引 ${event} 录波：正在读取 ${i+1}/64`);
      await fwReadOne(0xB23D+i,255);
    }
    fwQueryStatus(`查询索引 ${event} 录波：完成 64/64`);
  }catch(e){fwQueryStatus(`查询索引 ${event} 录波：${e.message}`);}
  finally{fwQuery.busy=false;}
}

// SN 帧沿用 book/SN_Builder.html 的固定模板；写入由用户明确操作触发。
const snTargets={outdoor:{name:'外机',address:0x7540,modbusId:0x01},indoor:{name:'内机',address:0x752f,modbusId:0xa1}};
const snMaintenanceReads=[
  {key:'advanced',name:'高阶参数使能',address:0x7572,frame:[0x7f,0x7f,0x11,0x19,0xc6,0xfd,0x1a,0,6,1,3,0x75,0x72,0,1,0x7f,0xcd,0xf7,0xf7]},
  {key:'upgrade',name:'强制升级使能',address:0x757a,frame:[0x7f,0x7f,0x11,0x19,0xc6,0xfd,0x1a,0,6,1,3,0x75,0x7a,0,1,0xfe,0x0f,0xf7,0xf7]}
];
function snVerifiedPage(){
  const page=fwPageControls(),text=document.body.innerText||'';
  const counts=text.match(/运行设备\s*(\d+)[\s\S]{0,120}?已连接\s*(\d+)/);
  if(!counts||Number(counts[1])!==1||Number(counts[2])!==1)throw new Error('请确认当前只有一台已连接设备');
  const active=text.match(/监听中\s*[·•]\s*([A-Za-z0-9_-]+)/);
  if(!active||active[1].toUpperCase()!==page.sn.toUpperCase())throw new Error('当前监听设备与 SN 列表不一致');
  return page;
}
function snBuildFrame(target,value){
  const info=snTargets[target];if(!info)throw new Error('未知的写入目标');
  if(typeof value!=='string'||!value.length||!value.trim())throw new Error('请输入 SN');
  if(value.length>16)throw new Error('SN 不能超过 16 个字符');
  if(!/^[\x20-\x7e]+$/.test(value))throw new Error('SN 只能包含 ASCII 可见字符');
  const serial=Array.from(value,c=>c.charCodeAt(0));while(serial.length<16)serial.push(0);
  const body=[0x11,0x19,0xc6,0xfd,0x1a,0,0x19,info.modbusId,0x10,info.address>>8,info.address&255,0,9,0x12,0,0xaa,...serial];
  const check=crc16(body);return [0x7f,0x7f,...body,check&255,check>>8,0xf7,0xf7];
}
function snSetStatus(target,text,error=false){const e=document.getElementById('fox-sn-'+target+'-status');if(e){e.textContent=text;e.style.color=error?'#b91c1c':'#64748b';}}
function snRefresh(target){
  const input=document.getElementById('fox-sn-'+target+'-input'),out=document.getElementById('fox-sn-'+target+'-frame');
  if(!input||!out)return;
  if(!input.value){out.value='';snSetStatus(target,'输入 SN 后自动生成报文');return;}
  try{const frame=snBuildFrame(target,input.value);out.value=fwHex(frame);snSetStatus(target,`已生成 · ${input.value.length}/16 字符 · CRC ${fwHex(frame.slice(-4,-2))}`);}
  catch(e){out.value='';snSetStatus(target,e.message,true);}
}
async function snCopy(target){
  const out=document.getElementById('fox-sn-'+target+'-frame');if(!out||!out.value){snSetStatus(target,'请先输入有效 SN',true);return;}
  try{await navigator.clipboard.writeText(out.value);snSetStatus(target,'报文已复制');}
  catch(e){try{out.focus();out.select();if(!document.execCommand('copy'))throw new Error();snSetStatus(target,'报文已复制');}catch(err){snSetStatus(target,'复制失败，请手动选择报文复制',true);}}
}
function snSetButtonsBusy(busy){
  document.querySelectorAll('#fox-view-sn [data-sn-operation]').forEach(button=>{button.disabled=busy;});
}
async function snQueryMaintenance(query){
  if(fwQuery.busy){snSetStatus(query.key,'当前有其他查询或写入进行中',true);return;}
  fwQuery.busy=true;fwQuery.stopped=false;fwQuery.interference=false;
  snSetButtonsBusy(true);snSetStatus(query.key,'正在查询…');
  try{
    const payload=await fwExchange(3,query.address,1,true);
    const value=readU16(payload,3),hex='0x'+value.toString(16).toUpperCase().padStart(4,'0');
    snSetStatus(query.key,value===0x00aa?`已使能（${hex}）`:`寄存器值 ${hex}`);
  }catch(e){snSetStatus(query.key,e.message,true);}
  finally{fwQuery.busy=false;snSetButtonsBusy(false);}
}
function snSendFrame(page,frame,target,expectedValue){
  return new Promise((resolve,reject)=>{
    const cmdText=fwHex(frame),initial=new Set(fwFindResponses()),previous=page.input.value,info=snTargets[target];
    let done=false,observer=null,timer=null,poll=null;
    const finish=err=>{if(done)return;done=true;clearTimeout(timer);clearInterval(poll);if(observer)observer.disconnect();
      try{if(page.input.value===cmdText)fwSetPageInput(page.input,previous);}catch(e){}err?reject(err):resolve();};
    const check=()=>{
      for(const text of fwFindResponses()){
        if(initial.has(text)||!/\bRECV\b/i.test(text))continue;
        const matches=text.match(/7F\s+7F\s+91(?:\s+[0-9A-F]{2})+\s+F7\s+F7/gi)||[];
        for(const raw of matches){
          const b=hexToBytes(raw);if(b.length<16||b[3]!==0x19||b[4]!==0xc6||b[5]!==0xfd||b[6]!==0x1a)continue;
          const len=(b[7]<<8)|b[8];if(b.length!==len+13||crc16(b.slice(2,-4))!==(b[b.length-4]|b[b.length-3]<<8))continue;
          const p=b.slice(9,9+len);if(p[0]!==info.modbusId)continue;
          if(p[1]===0x90&&p.length>=3){finish(new Error('设备返回写入异常码 0x'+p[2].toString(16).toUpperCase().padStart(2,'0')));return;}
          if(p[1]!==0x10||(p.length!==6&&p.length!==8)||p[2]!==info.address>>8||p[3]!== (info.address&255)||p[4]!==0||p[5]!==9)continue;
          if(p.length===8&&crc16(p.slice(0,6))!==(p[6]|p[7]<<8))continue;
          finish();return;
        }
      }
    };
    try{
      observer=new MutationObserver(check);observer.observe(document.body,{childList:true,subtree:true,characterData:true});
      timer=setTimeout(()=>finish(new Error('未收到可确认的写入响应，结果未知；请先读取设备属性核对 SN，不要重复写入')),12000);
      poll=setInterval(check,200);fwSetPageInput(page.input,cmdText);
    }catch(e){finish(e);return;}
    setTimeout(()=>{if(done)return;try{const current=snVerifiedPage();if(current.sn!==page.sn||current.input!==page.input||current.button!==page.button)throw new Error('连接目标已变化，未发送写入');if(document.getElementById('fox-sn-'+target+'-input').value!==expectedValue)throw new Error('SN 已变化，未发送写入');page.button.click();}catch(e){finish(e);}},100);
  });
}
async function snWrite(target){
  const info=snTargets[target],input=document.getElementById('fox-sn-'+target+'-input');
  if(!info||!input)return;
  if(fwQuery.busy){snSetStatus(target,'当前有其他查询或写入进行中',true);return;}
  let page,frame,value=input.value;
  try{frame=snBuildFrame(target,value);page=snVerifiedPage();}
  catch(e){snSetStatus(target,e.message,true);return;}
  const note=target==='indoor'?'\n内机模板由现有地址推导，尚未通过平台实机验证。':'';
  if(!window.confirm(`确认写入${info.name} SN？\n连接设备：${page.sn}\n${info.name} SN：${JSON.stringify(value)}\nModbus ID：0x${info.modbusId.toString(16).toUpperCase().padStart(2,'0')}\n地址：0x${info.address.toString(16).toUpperCase()}${note}`))return;
  try{const current=snVerifiedPage();if(current.sn!==page.sn)throw new Error('连接目标已变化，未发送写入');if(input.value!==value)throw new Error('SN 已变化，未发送写入');}
  catch(e){snSetStatus(target,e.message,true);return;}
  fwQuery.busy=true;snSetButtonsBusy(true);snSetStatus(target,'正在发送并等待设备响应…');
  try{await snSendFrame(page,frame,target,value);snSetStatus(target,'已收到写入响应；请读取设备属性确认 SN 已生效。');}
  catch(e){snSetStatus(target,e.message,true);}
  finally{fwQuery.busy=false;snSetButtonsBusy(false);}
}

