  'sgReady':'SG Ready','sgTclmin':'SG最低制冷温度','sgThtmax':'SG最高制热温度','sgTwmax':'SG最高热水温度','zone1Temp':'Z1区温度','zone2Temp':'Z2区温度','zone3Temp':'Z3区温度','heatingSetTemp':'制热设定温度','thermalOffOutdoorTemperature':'热关断室外温度',
