function exportLog(){
  const lines=['时间,命令码,SN,CRC,解析字段'];
  const cell=value=>'"'+String(value??'').replace(/"/g,'""')+'"';
  for(const f of capturedFrames.filter(frameMatchesSn)){
    const parsed=f.parsed||[],sn=(parsed.find(p=>p.name&&p.name.includes('SN'))||{}).value||'';
    const detail=parsed.map(p=>`${p.name}=${String(p.value).replace(/\n/g,' | ')}${p.unit||''}`).join('; ');
    const time=new Date(f.time),timeText=Number.isNaN(time.getTime())?String(f.time??''):time.toISOString();
    lines.push([timeText,'0x'+f.cmd,sn,f.crcOk?'OK':'FAIL',detail].map(cell).join(','));
  }
  const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8;'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=`foxess_log_${new Date().toISOString().slice(0,19).replace(/[:T]/g,'-')}.csv`;
  a.click();
}
